    spec_key: 'tuner', 'assessor', 'advisor'
    """
    if spec_key not in experiment_config:
        return True
    if 'class_args' not in experiment_config[spec_key]:
        return True
    if 'class_filename' not in experiment_config[spec_key]['class_args']:
        return True
